//
//  Fractals (Mandelbrot, Julia)
//  Native Metal Shader - Mathematical Art
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float zoom;
    float iterations;
    float julia_c_x;
    float julia_c_y;
    float center_x;       // pan center X
    float center_y;       // pan center Y
    float rotation;       // radians
    float color_freq;     // palette frequency
    float glow_strength;  // emission
    float julia_mix;      // 0..1 mix Mandelbrot/Julia
    float time_speed;     // time animation speed
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// Mandelbrot set
float mandelbrot(float2 c, int maxIter) {
    float2 z = float2(0.0);
    int iter = 0;

    for (int i = 0; i < maxIter; i++) {
        if (dot(z, z) > 4.0) break;

        // z = z^2 + c
        float xtemp = z.x * z.x - z.y * z.y + c.x;
        z.y = 2.0 * z.x * z.y + c.y;
        z.x = xtemp;

        iter++;
    }

    return float(iter) / float(maxIter);
}

// Julia set
float julia(float2 z, float2 c, int maxIter) {
    int iter = 0;

    for (int i = 0; i < maxIter; i++) {
        if (dot(z, z) > 4.0) break;

        // z = z^2 + c
        float xtemp = z.x * z.x - z.y * z.y + c.x;
        z.y = 2.0 * z.x * z.y + c.y;
        z.x = xtemp;

        iter++;
    }

    return float(iter) / float(maxIter);
}

// Color palette (adjustable frequency)
float3 palette(float t, float freq) {
    float3 a = float3(0.5, 0.5, 0.5);
    float3 b = float3(0.5, 0.5, 0.5);
    float3 c = float3(1.0, 1.0, 1.0);
    float3 d = float3(0.0, 0.33, 0.67);

    return a + b * cos(6.28318 * freq * (c * t + d));
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float4 originalColor = sourceTexture.sample(textureSampler, in.texCoord);

    // Map to complex plane
    float2 uv = (in.texCoord - 0.5) * 2.0;
    uv.x *= uniforms.OutputSize.x / uniforms.OutputSize.y;

    float time = float(uniforms.FrameCount) * 0.01 * uniforms.time_speed;

    // Zoom and pan
    uv /= uniforms.zoom;
    // Apply rotation
    float s = sin(uniforms.rotation), rotC = cos(uniforms.rotation);
    uv = float2(rotC*uv.x - s*uv.y, s*uv.x + rotC*uv.y);
    // Pan
    uv += float2(uniforms.center_x, uniforms.center_y);

    int maxIter = int(uniforms.iterations);

    // Julia set with animated c
    float2 jc = float2(uniforms.julia_c_x, uniforms.julia_c_y);
    jc += float2(cos(time * 0.3), sin(time * 0.5)) * 0.3;

    float juliaValue = julia(uv, jc, maxIter);

    // Mandelbrot set
    float mandelbrotValue = mandelbrot(uv, maxIter);

    // Mix both fractals
    float fractalValue = mix(mandelbrotValue, juliaValue, clamp(uniforms.julia_mix, 0.0, 1.0));

    // Apply color palette
    float3 fractalColor = palette(fractalValue, max(0.1, uniforms.color_freq));
    // Glow/emission accent near boundary
    float edge = smoothstep(0.0, 0.02, abs(fractalValue - 0.5));
    fractalColor += uniforms.glow_strength * (1.0 - edge);

    // Blend with original image
    float3 result = mix(originalColor.rgb, fractalColor, 0.7);

    return float4(result, 1.0);
}

